void Solver::bump_var(int var, double coeff) {
    static const double LIMIT = 1e100;
    static const double SCALE = 1e-100;
    static double max_act = 0.0;               // tracks the current maximum activity

    // increase activity of the variable
    double inc = var_inc * coeff;
    activity[var] += inc;

    // update the global maximum and rescale if needed
    if (activity[var] > max_act) max_act = activity[var];
    if (max_act > LIMIT) {
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
        max_act *= SCALE;
    }

    // maintain VSIDS priority queue
    if (vsids.inHeap(var)) vsids.update(var);
}
